function caloriesDialog(id=''){const c=state.calories.find(c=>c.id===id)||{date:C.ui.calorieDate||TODAY(),description:'',kcal:''},recent=id?[]:[...new Map([...state.calories].sort((a,b)=>b.date.localeCompare(a.date)).filter(x=>x.description).map(x=>[x.description.toLowerCase()+'|'+x.kcal+'|'+(x.protein??''),x])).values()].slice(0,6);const d=modal(id?'Edit calorie entry':'Add calories',`<div class="form-grid">${field('date','Date',c.date,'date','required max="'+TODAY()+'"')}${field('kcal','Calories (kcal)',c.kcal,'number','required min="1" max="20000" step="1"')}${field('protein','Protein (g) · optional',c.protein??'','number','min="0" max="1000" step="any"')}<div class="wide">${field('description','Description · optional',c.description,'text','maxlength="160"')}</div></div>${recent.length?`<div class="quick-picks"><span class="meta">Log again</span>${recent.map((r,i)=>`<button type="button" class="btn small" data-fill="${i}">${esc(r.description)} · ${r.kcal}${r.protein!=null?' · '+num(r.protein,1)+' g':''}</button>`).join('')}</div>`:''}`,async fd=>{const v={id:id||uid(),date:fd.get('date'),kcal:Number(fd.get('kcal')),description:fd.get('description').trim()},protein=fd.get('protein');if(!(v.kcal>0&&v.kcal<=20000&&Number.isInteger(v.kcal)))throw Error('Enter a whole number from 1 to 20,000 calories.');if(protein!==''&&protein!==null){v.protein=Number(protein);if(!(v.protein>=0&&v.protein<=1000))throw Error('Enter protein from 0 to 1,000 g, or leave it blank.')}state.calories=id?state.calories.map(c=>c.id===id?v:c):[...state.calories,v];state.calorieDays=state.calorieDays.filter(d=>d!==v.date&&d!==c.date);await save('Calorie entry saved')});d.querySelectorAll('[data-fill]').forEach(b=>b.onclick=()=>{const r=recent[Number(b.dataset.fill)];d.querySelector('[name=kcal]').value=r.kcal;d.querySelector('[name=description]').value=r.description;d.querySelector('[name=protein]').value=r.protein??'';d.querySelector('[type=submit]').focus()})}
