function bindUnitSwitch(form){const units=form?.querySelector('[name=units]');if(!units)return;let shown=units.value;units.addEventListener('change',()=>{const to=units.value;if(to===shown)return;for(const name of ['weight','targetWeight','height']){const input=form.querySelector(`[name=${name}]`);if(!input)continue;const length=name==='height',fromImperial=shown==='imperial',untouched=input.dataset.written!==undefined?input.value===input.dataset.written:input.value===input.defaultValue;let metric=untouched&&input.dataset.metric!==undefined?Number(input.dataset.metric):untouched&&state.profile[name]!==null?state.profile[name]:input.value!==''&&Number.isFinite(Number(input.value))?(fromImperial?(length?inToCm:lbToKg)(Number(input.value)):Number(input.value)):null;if(metric!==null){const shownValue=to==='imperial'?(length?cmToIn:kgToLb)(metric):metric;input.value=String(Math.round(shownValue*10)/10);input.dataset.metric=String(metric);input.dataset.written=input.value}input.removeAttribute('data-original-number');const label=form.querySelector(`label[for="${input.id}"]`);if(label)label.textContent=label.textContent.replace(/\((kg|cm|lb|in)\)/,m=>({'(kg)':'(lb)','(cm)':'(in)','(lb)':'(kg)','(in)':'(cm)'})[m])}shown=to})}
