function renderTimer(){document.querySelector('.timer')?.remove();if(restEnd===null||!state)return;const over=Date.now()-restEnd;if(over>20000){setRest(null);return}const seconds=Math.max(0,Math.ceil(-over/1000)),t=document.createElement('div');if(!seconds&&!restDone){restDone=true;if(over<2000)restAlert()}t.className='timer';t.setAttribute('role','status');t.innerHTML=`<div><small>${seconds?'Rest timer':'Rest complete'}</small><br><strong>${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}</strong></div><button data-action="timer-add:30" aria-label="Add 30 seconds" class="timer-add">+30s</button><button data-action="stop-timer" aria-label="Dismiss timer">${icon('close')}</button>`;document.body.append(t)}
setInterval(()=>{if(restEnd!==null)renderTimer();updateElapsed()},1000);
async function prepareOffline(refresh=false){if(isNative){C.offlineStatus='Installed Android app: every app file, the exercise library, illustrations and evidence summaries are on this device. Source links still need internet access.';return}if(!('serviceWorker'in navigator)){C.offlineStatus='This browser does not support offline caching. The downloaded source can still be served locally.';return}try{const hadController=!!navigator.serviceWorker.controller,registration=await navigator.serviceWorker.register('/sw.js');if(hadController&&!prepareOffline.watching){prepareOffline.watching=true;navigator.serviceWorker.addEventListener('controllerchange',()=>toast('Kinetic was updated. Reload when convenient to use the new version.'))}await navigator.serviceWorker.ready;if(refresh)await registration.update();const keys=await caches.keys();C.offlineStatus=keys.some(k=>k.startsWith('kinetic-shell-'))?'Offline files cached. Journal, evidence, exercises and anatomy are available without internet.':'Offline files are still preparing. Keep this page open until caching completes.'}catch{C.offlineStatus='Offline caching is unavailable in this browser. Records remain local; use a local copy for reliable offline access.'}const el=document.querySelector('#offline-state');if(el)el.textContent=C.offlineStatus}
window.addEventListener('hashchange',()=>{document.querySelector('#modal').close();if(location.hash!=='#training')closeFocus(false);render();document.querySelector('#main')?.focus({preventScroll:true});window.scrollTo(0,0)});window.addEventListener('online',()=>{if(state)render();checkForUpdates(C)});window.addEventListener('offline',()=>{if(state)render()});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();C.installPrompt=e});
if(document.modelContext?.registerTool){try{const lifecycle=new AbortController();document.modelContext.registerTool({name:'start_kinetic_calorie_entry',title:'Start a calorie entry',description:'Open the manual calorie-entry dialog. Stages an entry; does not save calories.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(input&&Object.keys(input).length)throw Error('This tool takes no arguments.');if(!state)throw Error('Unlock the local journal first.');caloriesDialog();return {status:'entry_dialog_open'}}},{signal:lifecycle.signal});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{/* Optional proposed browser API. */}}
try{const loaded=await loadState();const assets=await Promise.all([fetch('/assets/evidence.json').then(r=>{if(!r.ok)throw Error('Evidence asset unavailable');return r.json()}),fetch('/assets/muscle-map.json').then(r=>r.json()),fetch('/assets/front.svg').then(r=>r.text()),fetch('/assets/back.svg').then(r=>r.text())]);C.evidence=assets[0];C.evidence.sources.push(...anatomySources);C.anatomyMap=assets[1];C.svg.front=assets[2];C.svg.back=assets[3];try{buildFigureDefs(C)}catch{/* Figures fall back to empty outlines. */}if(loaded.locked){envelope=loaded.envelope;renderLocked()}else{state=validateState(loaded.state);lastGood=structuredClone(state);render();if(!prefs.tourSeen){if(isFreshJournal(state))startSetup(C);else startTour(C)}}try{C.persisted=navigator.storage?.persisted?await navigator.storage.persisted():null}catch{C.persisted=null}checkForUpdates(C);await prepareOffline()}catch(error){document.querySelector('#app').innerHTML=`<main class="locked card"><h1>Journal unavailable</h1><p>${esc(error.message)}</p><p class="note-box">Check that this browser allows local storage and the app files are available. Saved records have not been replaced.</p><button class="btn primary" onclick="location.reload()">Try again</button></main>`}

function focusDescriptor(el){if(!el||document.querySelector('#modal').contains(el))return null;if(el.dataset.action)return '[data-action="'+CSS.escape(el.dataset.action)+'"]';if(el.name)return '[name="'+CSS.escape(el.name)+'"]';if(el.dataset.setField){const row=el.closest('[data-set]');return '[data-set="'+CSS.escape(row.dataset.set)+'"] [data-set-field="'+el.dataset.setField+'"]'}return el.id?'#'+CSS.escape(el.id):null}
function restoreFocus(selector){if(selector){const next=document.querySelector(selector);if(next&&!next.closest('[inert]'))next.focus({preventScroll:true})}}
function syncNavigation(){const side=document.querySelector('.sidebar'),workspace=document.querySelector('.workspace'),button=document.querySelector('.menu-toggle');if(!side)return;const mobile=matchMedia('(max-width:800px)').matches,open=mobile&&side.classList.contains('open');side.inert=mobile&&!open;if(workspace)workspace.inert=open;button?.setAttribute('aria-expanded',String(open))}
function closeNavigation(){const side=document.querySelector('.sidebar');if(side?.classList.contains('open')){side.classList.remove('open');syncNavigation();document.querySelector('.menu-toggle')?.focus({preventScroll:true})}}
matchMedia('(max-width:800px)').addEventListener('change',syncNavigation);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNavigation()});document.addEventListener('click',e=>{const side=document.querySelector('.sidebar');if(side?.classList.contains('open')&&!side.contains(e.target)&&!e.target.closest('.menu-toggle'))closeNavigation()});
